1	// sc4sap:package-to-process — BPML (Business Process Master List) builder.
2	// Emits .xlsx (styled two-sheet workbook) OR .md (same data as Markdown) —
3	// CLI picks the mode from the output file extension.
4	//
5	// LANGUAGE: overview sheet name + every label follows meta.language
6	// (built-in dictionaries ko/en/ja, unknown → en; meta.labels overrides any
7	// key for other languages). The BPML sheet name is ALWAYS English "BPML"
8	// (lingua franca) regardless of language.
9	//
10	// xlsx shape:
11	//   Sheet 1 (localized 개요/Overview/概要) —
12	//                       dark 14pt title banner (row 1, merged A1:D1) +
13	//                       package meta + entry-point summary + WRICEF legend +
14	//                       "(추정)/(확인필요)" notation guide (values merged B:D
15	//                       so long text never gets buried)
16	//   Sheet 2 「BPML」  — STAIRCASE hierarchy matrix: every level L1~L5 gets its
17	//                       OWN row. Each L1 GROUP gets its own color family
18	//                       (blue / green / orange / purple / teal, cycling);
19	//                       shading applies to L1·L2 ONLY (L3+ stay white so the
20	//                       sheet isn't a wall of color). Dark header, frozen
21	//                       header row, AutoFilter, light-yellow highlight on
22	//                       "(확인필요)". Whole workbook font = 굴림.
23	//
24	// Column widths are AUTO-COMPUTED from content (Korean glyphs ≈ 2 units);
25	// long-text columns get a generous cap (업무 내용 = 100). Row height is a
26	// FLAT 16 everywhere (exceptions: overview title banner 30, notation-guide
27	// wrap row) — no auto multi-line heights.
28	//
29	// Zero external deps — OOXML assembled by hand, zipped via xlsx-zip.mjs.
30	//
31	// INPUT JSON SHAPE
32	//   {
33	//     "meta": { package, module, sap_version, abap_release, industry, country,
34	//               active_modules[], generated_at, language,
35	//               entry_points:[{program,tcode,short,persona}],
36	//               wricef_legend:{...} },
37	//     "rows": [
38	//       // hierarchy row (lv 1–4): label goes in its own level column
39	//       { "lv":1, "code":"1",     "l1":"구매관리", "task_desc":"…요약…" },
40	//       { "lv":2, "code":"1.1",   "l2":"구매요청(PR) 관리", "task_desc":"…" },
41	//       // leaf row (lv 5): carries program attributes
42	//       { "lv":5, "code":"1.1.1.1.1", "l5":"PR 결재현황 조회",
43	//         "program","tcode","std_cbo","task_desc","io","wricef",
44	//         "dept","legacy","note" }
45	//     ]
46	//   }
47	//   Any cell string containing "확인필요" is auto-highlighted yellow.
48	//   Group color = first segment of `code` (1-based) cycling the palette.
49	//   프로세스ID (column between 프로세스코드 and L1) is AUTO-NUMBERED by the
50	//   builder for L5 rows only — [meta.module]-001, -002, … in document order.
51	//   Do NOT supply `proc_id` in the JSON; it is overwritten.
52	//
53	// CLI
54	//   node build-bpml.mjs <bpml.json> <out.xlsx>   → styled workbook
55	//   node build-bpml.mjs <bpml.json> <out.md>     → same data as Markdown
56	//   (run twice for both formats)
57	//
58	// md mode extras: after the BPML table, every L2–L5 row gets a detail
59	// section (title + description + diagram SVG in _img/bpml-flows-<lang>/);
60	// the table's process-code cells hyperlink to those sections. Image pick
61	// order per row: `seq` (v13 horizontal scenario sequence diagram — same
62	// style as the process document; PREFERRED) → `flow: {nodes, edges}` (v12
63	// vertical flowchart) → auto-derived linear flow (last resort: L2–L4 =
64	// chain of direct children, L5 = 입력→task→출력 from `io`).
65	
66	import { readFileSync, writeFileSync, mkdirSync } from 'node:fs';
67	import { resolve, dirname, join } from 'node:path';
68	import { fileURLToPath } from 'node:url';
69	import { zipFiles } from './xlsx-zip.mjs';
70	import { renderFlowchartSVG, renderSequenceDiagramSVG } from './screen-image-renderer.mjs';
71	
72	// ── Column model — key · max width cap · centered (headers → L10N) ──────
73	const COLUMNS = [
74	  { key: 'lv',        cap: 5,   center: true, num: true },
75	  { key: 'code',      cap: 14 },               // left-aligned
76	  { key: 'proc_id',   cap: 14,  center: true }, // L5 채번: [모듈]-001…
77	  { key: 'l1',        cap: 20 },
78	  { key: 'l2',        cap: 22 },
79	  { key: 'l3',        cap: 24 },
80	  { key: 'l4',        cap: 26 },
81	  { key: 'l5',        cap: 28 },
82	  { key: 'program',   cap: 15,  center: true },
83	  { key: 'tcode',     cap: 13,  center: true },
84	  { key: 'std_cbo',   cap: 10,  center: true },
85	  { key: 'task_desc', cap: 100 },
86	  { key: 'io',        cap: 80 },
87	  { key: 'wricef',    cap: 11,  center: true },
88	  { key: 'dept',      cap: 18 },
89	  { key: 'legacy',    cap: 60 },
90	  { key: 'note',      cap: 26 },
91	];
92	const NCOL = COLUMNS.length;
93	
94	// ── L10N — meta.language picks the dictionary (ko/en/ja, unknown → en);
95	//    meta.labels {overviewSheet?, title?, headers?{}, ov?{}} overrides keys
96	//    so any other language can be supplied at runtime. BPML sheet name is
97	//    intentionally NOT localizable.
98	const L10N = {
99	  ko: {
100	    overviewSheet: '개요',
101	    title: '업무 프로세스 마스터리스트 (BPML)',
102	    headers: { lv: 'Lv', code: '프로세스코드', proc_id: '프로세스ID', l1: 'L1 대분류', l2: 'L2 중분류', l3: 'L3 소분류', l4: 'L4 단위업무', l5: 'L5 Task(단위활동)', program: '프로그램/FM', tcode: 'TCode/실행', std_cbo: '표준/CBO', task_desc: '업무 내용', io: '입력/출력', wricef: 'WRICEF', dept: '담당부서', legacy: '연관 레거시', note: '비고' },
103	    ov: { pkgBand: '패키지 개요', package: '패키지', module: '모듈', sapVersion: 'SAP 버전', abapRelease: 'ABAP 릴리즈', industry: '산업', country: '국가', activeModules: '활성 모듈', generatedAt: '생성 일시', language: '언어', levelCounts: '레벨별 행 수', epBand: '진입점 요약', epProgram: '프로그램', epTcode: 'TCode', epShort: '기능 설명', epPersona: '전형적 사용자', legendBand: 'WRICEF 범례', guideBand: '표기 안내', guide: '"(추정)" · "(확인필요)" 로 표기된 값(담당부서·연관 레거시 등)은 ABAP 코드에서 직접 추출되지 않아 AI가 추정한 값입니다. 실제 조직도·인터페이스 목록으로 검증 후 확정하세요. 노란색 셀 = 확인 필요.' },
104	    flow: { detailBand: '프로세스 상세', start: '시작', end: '종료', backToTable: '↑ BPML 표로', desc: '설명' },
105	  },
106	  en: {
107	    overviewSheet: 'Overview',
108	    title: 'Business Process Master List (BPML)',
109	    headers: { lv: 'Lv', code: 'Process Code', proc_id: 'Process ID', l1: 'L1 Category', l2: 'L2 Group', l3: 'L3 Subgroup', l4: 'L4 Work Unit', l5: 'L5 Task (Activity)', program: 'Program/FM', tcode: 'TCode/Exec', std_cbo: 'Std/CBO', task_desc: 'Task Description', io: 'Input/Output', wricef: 'WRICEF', dept: 'Owning Dept', legacy: 'Related Legacy', note: 'Notes' },
110	    ov: { pkgBand: 'Package Overview', package: 'Package', module: 'Module', sapVersion: 'SAP Version', abapRelease: 'ABAP Release', industry: 'Industry', country: 'Country', activeModules: 'Active Modules', generatedAt: 'Generated At', language: 'Language', levelCounts: 'Rows per Level', epBand: 'Entry-Point Summary', epProgram: 'Program', epTcode: 'TCode', epShort: 'Description', epPersona: 'Typical User', legendBand: 'WRICEF Legend', guideBand: 'Notation Guide', guide: 'Values marked "(estimated)" or "(TBD)" (owning dept, related legacy, etc.) were inferred by AI, not extracted from ABAP code. Verify against the actual org chart / interface list before finalizing. Yellow cells = needs confirmation.' },
111	    flow: { detailBand: 'Process Details', start: 'Start', end: 'End', backToTable: '↑ Back to BPML', desc: 'Description' },
112	  },
113	  ja: {
114	    overviewSheet: '概要',
115	    title: '業務プロセスマスターリスト (BPML)',
116	    headers: { lv: 'Lv', code: 'プロセスコード', proc_id: 'プロセスID', l1: 'L1 大分類', l2: 'L2 中分類', l3: 'L3 小分類', l4: 'L4 単位業務', l5: 'L5 タスク(単位活動)', program: 'プログラム/FM', tcode: 'TCode/実行', std_cbo: '標準/CBO', task_desc: '業務内容', io: '入力/出力', wricef: 'WRICEF', dept: '担当部署', legacy: '関連レガシー', note: '備考' },
117	    ov: { pkgBand: 'パッケージ概要', package: 'パッケージ', module: 'モジュール', sapVersion: 'SAPバージョン', abapRelease: 'ABAPリリース', industry: '業種', country: '国', activeModules: '有効モジュール', generatedAt: '生成日時', language: '言語', levelCounts: 'レベル別行数', epBand: 'エントリポイント要約', epProgram: 'プログラム', epTcode: 'TCode', epShort: '機能説明', epPersona: '典型ユーザー', legendBand: 'WRICEF凡例', guideBand: '表記ガイド', guide: '「(推定)」「(要確認)」と表記された値（担当部署・関連レガシーなど）はABAPコードから直接抽出されたものではなく、AIによる推定値です。実際の組織図・インターフェース一覧で検証のうえ確定してください。黄色セル＝要確認。' },
118	    flow: { detailBand: 'プロセス詳細', start: '開始', end: '終了', backToTable: '↑ BPML表へ', desc: '説明' },
119	  },
120	};
121	function pickLang(meta) {
122	  const code = String(meta.language || 'ko').toLowerCase().slice(0, 2);
123	  const base = L10N[code] || L10N.en;
124	  const o = meta.labels || {};
125	  return {
126	    ...base, ...o,
127	    headers: { ...base.headers, ...(o.headers || {}) },
128	    ov: { ...base.ov, ...(o.ov || {}) },
129	    flow: { ...base.flow, ...(o.flow || {}) },
130	  };
131	}
132	
133	// 프로세스ID 채번 — L5(leaf) 행에만 문서 순서대로 [모듈]-001, -002, … 부여.
134	function assignProcIds(meta, rows) {
135	  const modPrefix = String(meta.module || 'XX').toUpperCase();
136	  let seq = 0;
137	  for (const r of rows) {
138	    if (r.lv === 5) r.proc_id = `${modPrefix}-${String(++seq).padStart(3, '0')}`;
139	  }
140	}
141	
142	// ── Per-L1-group color families — shading L1·L2 ONLY (L3+ = white) ──────
143	const GROUP_PALETTES = [
144	  ['FF9DC3E6', 'FFDDEBF7'],   // 1 blue
145	  ['FFA9D08E', 'FFE2EFDA'],   // 2 green
146	  ['FFF4B183', 'FFFCE4D6'],   // 3 orange
147	  ['FFB1A0C7', 'FFE4DFEC'],   // 4 purple
148	  ['FF8ED0CD', 'FFDAF0EF'],   // 5 teal
149	];
150	const NGROUP = GROUP_PALETTES.length;
151	
152	// ── XML / text helpers ──────────────────────────────────────────────────
153	const esc = (s) => String(s ?? '')
154	  .replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;')
155	  .replace(/"/g, '&quot;');
156	
157	function colLetter(n) {
158	  let s = '', x = n;
159	  do { s = String.fromCharCode(65 + (x % 26)) + s; x = Math.floor(x / 26) - 1; } while (x >= 0);
160	  return s;
161	}
162	const WARN_MARKERS = ['확인필요', '要確認', 'TBD'];
163	const isWarn = (v) => typeof v === 'string' && WARN_MARKERS.some((m) => v.includes(m));
164	
165	// Display width in Excel column units: ASCII ≈ 1.0, CJK(굴림) ≈ 2.0.
166	function dispW(s) {
167	  let w = 0;
168	  for (const ch of String(s ?? '')) w += ch.codePointAt(0) > 255 ? 2.0 : 1.05;
169	  return w;
170	}
171	
172	function cell(colIdx, rowNum, value, style, type) {
173	  const ref = `${colLetter(colIdx)}${rowNum}`;
174	  const s = style != null ? ` s="${style}"` : '';
175	  if (value == null || value === '') return `<c r="${ref}"${s}/>`;
176	  if (type === 'n') return `<c r="${ref}"${s}><v>${esc(value)}</v></c>`;
177	  return `<c r="${ref}"${s} t="inlineStr"><is><t xml:space="preserve">${esc(value)}</t></is></c>`;
178	}
179	
180	// ── styles.xml (generated) — whole workbook font = 굴림 ─────────────────
181	// fonts: 0 굴림10 · 1 굴림10 bold white · 2 굴림10 bold · 3 굴림14 bold white
182	// fills: 0 none · 1 gray125 · 2 header FF595959 · 3 warn FFFFF2CC ·
183	//        4 ov-label FFE7E7E7 · 5.. group fills (g*2 + lv-1)
184	// cellXfs:
185	//   0 default · 1 header · 2 title(dark banner) · 3 ov-label · 4 ov-value
186	//   5 L5 base(white) · 6 L5 center · 7 warn
187	//   8.. group/level (L1·L2 only): base = 8 + (g*2 + lv-1)*2, center = base+1
188	const XF_L5 = 5, XF_WARN = 7, XF_GROUP0 = 8;
189	const groupXf = (g, lv, center) => XF_GROUP0 + (g * 2 + (lv - 1)) * 2 + (center ? 1 : 0);
190	
191	function stylesXml() {
192	  const fillDefs = ['<fill><patternFill patternType="none"/></fill>',
193	    '<fill><patternFill patternType="gray125"/></fill>',
194	    '<fill><patternFill patternType="solid"><fgColor rgb="FF595959"/></patternFill></fill>',
195	    '<fill><patternFill patternType="solid"><fgColor rgb="FFFFF2CC"/></patternFill></fill>',
196	    '<fill><patternFill patternType="solid"><fgColor rgb="FFE7E7E7"/></patternFill></fill>'];
197	  for (const pal of GROUP_PALETTES) for (const rgb of pal)
198	    fillDefs.push(`<fill><patternFill patternType="solid"><fgColor rgb="${rgb}"/></patternFill></fill>`);
199	
200	  const xfs = [
201	    '<xf numFmtId="0" fontId="0" fillId="0" borderId="0" xfId="0"/>',
202	    '<xf numFmtId="0" fontId="1" fillId="2" borderId="1" xfId="0" applyFont="1" applyFill="1" applyBorder="1" applyAlignment="1"><alignment horizontal="center" vertical="center" wrapText="1"/></xf>',
203	    '<xf numFmtId="0" fontId="3" fillId="2" borderId="1" xfId="0" applyFont="1" applyFill="1" applyBorder="1" applyAlignment="1"><alignment horizontal="center" vertical="center"/></xf>',
204	    '<xf numFmtId="0" fontId="2" fillId="4" borderId="1" xfId="0" applyFont="1" applyFill="1" applyBorder="1" applyAlignment="1"><alignment vertical="center" wrapText="1"/></xf>',
205	    '<xf numFmtId="0" fontId="0" fillId="0" borderId="1" xfId="0" applyBorder="1" applyAlignment="1"><alignment vertical="center" wrapText="1"/></xf>',
206	    '<xf numFmtId="0" fontId="0" fillId="0" borderId="1" xfId="0" applyBorder="1" applyAlignment="1"><alignment vertical="top" wrapText="1"/></xf>',
207	    '<xf numFmtId="0" fontId="0" fillId="0" borderId="1" xfId="0" applyBorder="1" applyAlignment="1"><alignment horizontal="center" vertical="center"/></xf>',
208	    '<xf numFmtId="0" fontId="0" fillId="3" borderId="1" xfId="0" applyFill="1" applyBorder="1" applyAlignment="1"><alignment vertical="top" wrapText="1"/></xf>',
209	  ];
210	  GROUP_PALETTES.forEach((pal, g) => {
211	    pal.forEach((_, li) => {
212	      const fillId = 5 + g * 2 + li;
213	      const fontId = li === 0 ? 2 : 0;                    // L1 rows bold
214	      xfs.push(`<xf numFmtId="0" fontId="${fontId}" fillId="${fillId}" borderId="1" xfId="0" applyFont="1" applyFill="1" applyBorder="1" applyAlignment="1"><alignment vertical="center" wrapText="1"/></xf>`);
215	      xfs.push(`<xf numFmtId="0" fontId="${fontId}" fillId="${fillId}" borderId="1" xfId="0" applyFont="1" applyFill="1" applyBorder="1" applyAlignment="1"><alignment horizontal="center" vertical="center"/></xf>`);
216	    });
217	  });
218	
219	  return `<?xml version="1.0" encoding="UTF-8" standalone="yes"?>
220	<styleSheet xmlns="http://schemas.openxmlformats.org/spreadsheetml/2006/main">
221	<fonts count="4">
222	<font><sz val="10"/><name val="굴림"/></font>
223	<font><sz val="10"/><b/><color rgb="FFFFFFFF"/><name val="굴림"/></font>
224	<font><sz val="10"/><b/><name val="굴림"/></font>
225	<font><sz val="14"/><b/><color rgb="FFFFFFFF"/><name val="굴림"/></font>
226	</fonts>
227	<fills count="${fillDefs.length}">${fillDefs.join('')}</fills>
228	<borders count="2">
229	<border><left/><right/><top/><bottom/><diagonal/></border>
230	<border>
231	<left style="thin"><color rgb="FFA6A6A6"/></left>
232	<right style="thin"><color rgb="FFA6A6A6"/></right>
233	<top style="thin"><color rgb="FFA6A6A6"/></top>
234	<bottom style="thin"><color rgb="FFA6A6A6"/></bottom>
235	<diagonal/></border>
236	</borders>
237	<cellStyleXfs count="1"><xf numFmtId="0" fontId="0" fillId="0" borderId="0"/></cellStyleXfs>
238	<cellXfs count="${xfs.length}">${xfs.join('')}</cellXfs>
239	<cellStyles count="1"><cellStyle name="Normal" xfId="0" builtinId="0"/></cellStyles>
240	</styleSheet>`;
241	}
242	
243	// ── width auto-fit (row height is a flat 16 everywhere) ─────────────────
244	function computeWidths(rows, headers) {
245	  return COLUMNS.map((c, i) => {
246	    let w = dispW(headers[i]);
247	    for (const r of rows) w = Math.max(w, dispW(r[c.key]));
248	    return Math.min(Math.max(w + 2.5, 6), c.cap);
249	  });
250	}
251	
252	// ── BPML sheet ──────────────────────────────────────────────────────────
253	function bpmlSheetXml(rows, headers) {
254	  const widths = computeWidths(rows, headers);
255	  const colsXml = widths.map((w, i) =>
256	    `<col min="${i + 1}" max="${i + 1}" width="${w.toFixed(1)}" customWidth="1"/>`).join('');
257	
258	  const headerCells = COLUMNS.map((c, i) => cell(i, 1, headers[i], 1)).join('');
259	  const body = [`<row r="1" ht="16" customHeight="1">${headerCells}</row>`];
260	
261	  rows.forEach((r, ri) => {
262	    const rowNum = ri + 2;
263	    const seg1 = parseInt(String(r.code).split('.')[0], 10);
264	    const g = (Number.isFinite(seg1) && seg1 > 0 ? seg1 - 1 : 0) % NGROUP;
265	    const cells = COLUMNS.map((c, i) => {
266	      const raw = r[c.key];
267	      let style;
268	      if (isWarn(raw)) style = XF_WARN;
269	      else if (r.lv >= 3 || !r.lv) style = c.center ? XF_L5 + 1 : XF_L5;   // 음영은 L2까지만
270	      else style = groupXf(g, r.lv, c.center);
271	      return cell(i, rowNum, raw, style, c.num ? 'n' : undefined);
272	    }).join('');
273	    body.push(`<row r="${rowNum}" ht="16" customHeight="1">${cells}</row>`);
274	  });
275	
276	  const lastRef = `${colLetter(NCOL - 1)}${rows.length + 1}`;
277	  return `<?xml version="1.0" encoding="UTF-8" standalone="yes"?>
278	<worksheet xmlns="http://schemas.openxmlformats.org/spreadsheetml/2006/main">
279	<sheetViews><sheetView tabSelected="1" workbookViewId="0">
280	<pane ySplit="1" topLeftCell="A2" activePane="bottomLeft" state="frozen"/>
281	<selection pane="bottomLeft" activeCell="A2" sqref="A2"/></sheetView></sheetViews>
282	<sheetFormatPr defaultRowHeight="16" customHeight="1"/>
283	<cols>${colsXml}</cols>
284	<sheetData>${body.join('')}</sheetData>
285	<autoFilter ref="A1:${lastRef}"/>
286	<pageMargins left="0.3" right="0.3" top="0.5" bottom="0.5" header="0.3" footer="0.3"/>
287	</worksheet>`;
288	}
289	
290	// ── 개요/Overview sheet (labels from L10N `t`) ──────────────────────────
291	// Values merge B:D so long text (timestamps, legend prose, level counts)
292	// never gets visually buried behind the next cell border.
293	function overviewSheetXml(meta, counts, t) {
294	  const out = [];
295	  const merges = [];
296	  let r = 1;
297	  const push = (cells, ht) => {
298	    out.push(`<row r="${r}"${ht ? ` ht="${ht}" customHeight="1"` : ''}>${cells}</row>`);
299	    r++;
300	  };
301	  const band = (label) => push(cell(0, r, label, 1) + cell(1, r, '', 1) + cell(2, r, '', 1) + cell(3, r, '', 1), 16);
302	  const kv = (label, value) => {
303	    merges.push(`B${r}:D${r}`);
304	    push(cell(0, r, label, 3) + cell(1, r, value, 4) + cell(2, r, '', 4) + cell(3, r, '', 4), 16);
305	  };
306	
307	  // Title banner — style 2 (14pt bold white on dark) on EVERY merged cell so
308	  // Excel renders the full banner rectangle, not just the top-left cell.
309	  const title = `${meta.package || ''} — ${t.title}`;
310	  push(cell(0, r, title, 2) + cell(1, r, '', 2) + cell(2, r, '', 2) + cell(3, r, '', 2), 30);
311	  merges.push(`A1:D1`);
312	  push('');
313	
314	  band(t.ov.pkgBand);
315	  kv(t.ov.package, meta.package);
316	  kv(t.ov.module, meta.module);
317	  kv(t.ov.sapVersion, meta.sap_version);
318	  kv(t.ov.abapRelease, meta.abap_release);
319	  kv(t.ov.industry, meta.industry);
320	  kv(t.ov.country, meta.country);
321	  kv(t.ov.activeModules, (meta.active_modules || []).join(', '));
322	  kv(t.ov.generatedAt, meta.generated_at);
323	  kv(t.ov.language, meta.language);
324	  kv(t.ov.levelCounts, `L1 ${counts[1] || 0} · L2 ${counts[2] || 0} · L3 ${counts[3] || 0} · L4 ${counts[4] || 0} · L5 ${counts[5] || 0}`);
325	  push('');
326	
327	  const eps = meta.entry_points || [];
328	  if (eps.length) {
329	    band(t.ov.epBand);
330	    push(cell(0, r, t.ov.epProgram, 3) + cell(1, r, t.ov.epTcode, 3) + cell(2, r, t.ov.epShort, 3) + cell(3, r, t.ov.epPersona, 3), 16);
331	    for (const e of eps) {
332	      push(cell(0, r, e.program, 4) + cell(1, r, e.tcode || '-', 4) + cell(2, r, e.short, 4) + cell(3, r, e.persona, 4), 16);
333	    }
334	    push('');
335	  }
336	
337	  const leg = meta.wricef_legend || {};
338	  const legKeys = Object.keys(leg);
339	  if (legKeys.length) {
340	    band(t.ov.legendBand);
341	    for (const k of legKeys) kv(k, leg[k]);
342	    push('');
343	  }
344	
345	  band(t.ov.guideBand);
346	  merges.push(`A${r}:D${r}`);
347	  push(cell(0, r, t.ov.guide, 4) + cell(1, r, '', 4) + cell(2, r, '', 4) + cell(3, r, '', 4), 58);
348	
349	  const cols = `<col min="1" max="1" width="24" customWidth="1"/><col min="2" max="2" width="46" customWidth="1"/><col min="3" max="3" width="36" customWidth="1"/><col min="4" max="4" width="24" customWidth="1"/>`;
350	  const mergesXml = merges.length ? `<mergeCells count="${merges.length}">${merges.map((m) => `<mergeCell ref="${m}"/>`).join('')}</mergeCells>` : '';
351	  return `<?xml version="1.0" encoding="UTF-8" standalone="yes"?>
352	<worksheet xmlns="http://schemas.openxmlformats.org/spreadsheetml/2006/main">
353	<sheetViews><sheetView workbookViewId="0"/></sheetViews>
354	<sheetFormatPr defaultRowHeight="16" customHeight="1"/>
355	<cols>${cols}</cols>
356	<sheetData>${out.join('')}</sheetData>
357	${mergesXml}
358	<pageMargins left="0.5" right="0.5" top="0.6" bottom="0.6" header="0.3" footer="0.3"/>
359	</worksheet>`;
360	}
361	
362	// ── package parts ───────────────────────────────────────────────────────
363	function contentTypes() {
364	  return `<?xml version="1.0" encoding="UTF-8" standalone="yes"?>
365	<Types xmlns="http://schemas.openxmlformats.org/package/2006/content-types">
366	<Default Extension="rels" ContentType="application/vnd.openxmlformats-package.relationships+xml"/>
367	<Default Extension="xml" ContentType="application/xml"/>
368	<Override PartName="/xl/workbook.xml" ContentType="application/vnd.openxmlformats-officedocument.spreadsheetml.sheet.main+xml"/>
369	<Override PartName="/xl/worksheets/sheet1.xml" ContentType="application/vnd.openxmlformats-officedocument.spreadsheetml.worksheet+xml"/>
370	<Override PartName="/xl/worksheets/sheet2.xml" ContentType="application/vnd.openxmlformats-officedocument.spreadsheetml.worksheet+xml"/>
371	<Override PartName="/xl/styles.xml" ContentType="application/vnd.openxmlformats-officedocument.spreadsheetml.styles+xml"/>
372	</Types>`;
373	}
374	function rootRels() {
375	  return `<?xml version="1.0" encoding="UTF-8" standalone="yes"?>
376	<Relationships xmlns="http://schemas.openxmlformats.org/package/2006/relationships">
377	<Relationship Id="rId1" Type="http://schemas.openxmlformats.org/officeDocument/2006/relationships/officeDocument" Target="xl/workbook.xml"/>
378	</Relationships>`;
379	}
380	function workbookXml(overviewName) {
381	  // Sheet 1 name follows meta.language; sheet 2 is always English "BPML".
382	  return `<?xml version="1.0" encoding="UTF-8" standalone="yes"?>
383	<workbook xmlns="http://schemas.openxmlformats.org/spreadsheetml/2006/main" xmlns:r="http://schemas.openxmlformats.org/officeDocument/2006/relationships">
384	<sheets>
385	<sheet name="${esc(overviewName)}" sheetId="1" r:id="rId1"/>
386	<sheet name="BPML" sheetId="2" r:id="rId2"/>
387	</sheets>
388	</workbook>`;
389	}
390	function workbookRels() {
391	  return `<?xml version="1.0" encoding="UTF-8" standalone="yes"?>
392	<Relationships xmlns="http://schemas.openxmlformats.org/package/2006/relationships">
393	<Relationship Id="rId1" Type="http://schemas.openxmlformats.org/officeDocument/2006/relationships/worksheet" Target="worksheets/sheet1.xml"/>
394	<Relationship Id="rId2" Type="http://schemas.openxmlformats.org/officeDocument/2006/relationships/worksheet" Target="worksheets/sheet2.xml"/>
395	<Relationship Id="rId3" Type="http://schemas.openxmlformats.org/officeDocument/2006/relationships/styles" Target="styles.xml"/>
396	</Relationships>`;
397	}
398	
399	export function buildBpml({ meta = {}, rows = [], outPath }) {
400	  if (!outPath) throw new Error('build-bpml: outPath is required');
401	  if (!Array.isArray(rows) || rows.length === 0) throw new Error('build-bpml: rows[] is empty');
402	  const t = pickLang(meta);
403	  const headers = COLUMNS.map((c) => t.headers[c.key]);
404	  const counts = {};
405	  for (const r of rows) counts[r.lv] = (counts[r.lv] || 0) + 1;
406	  assignProcIds(meta, rows);
407	
408	  const entries = [
409	    { name: '[Content_Types].xml', data: Buffer.from(contentTypes(), 'utf8') },
410	    { name: '_rels/.rels', data: Buffer.from(rootRels(), 'utf8') },
411	    { name: 'xl/workbook.xml', data: Buffer.from(workbookXml(t.overviewSheet), 'utf8') },
412	    { name: 'xl/_rels/workbook.xml.rels', data: Buffer.from(workbookRels(), 'utf8') },
413	    { name: 'xl/styles.xml', data: Buffer.from(stylesXml(), 'utf8') },
414	    { name: 'xl/worksheets/sheet1.xml', data: Buffer.from(overviewSheetXml(meta, counts, t), 'utf8') },
415	    { name: 'xl/worksheets/sheet2.xml', data: Buffer.from(bpmlSheetXml(rows, headers), 'utf8') },
416	  ];
417	  const buf = zipFiles(entries);
418	  mkdirSync(dirname(outPath), { recursive: true });
419	  writeFileSync(outPath, buf);
420	  return { outPath, bytes: buf.length, rows: rows.length, counts };
421	}
422	
423	// ── Auto flow graph for one row (md detail sections) ────────────────────
424	// L2–L4: linear chain of DIRECT children (next-level rows until the level
425	// pops back). L5: 입력 → task(program·tcode) → 출력 parsed from `io`.
426	// A row may override with its own `flow: {nodes, edges}` (renderer schema).
427	function autoFlowGraph(rows, idx, t) {
428	  const r = rows[idx];
429	  if (r.flow && Array.isArray(r.flow.nodes) && r.flow.nodes.length) return r.flow;
430	  const nodes = [], edges = [];
431	  const chain = (ids) => { for (let i = 0; i < ids.length - 1; i++) edges.push({ from: ids[i], to: ids[i + 1] }); };
432	  if (r.lv === 5) {
433	    const io = String(r.io || '');
434	    const mIn = io.match(/(?:입력|Input|入力)\s*[::]\s*([^/]+)/i);
435	    const mOut = io.match(/(?:출력|Output|出力)\s*[::]\s*(.+)$/i);
436	    const sub = [r.program, r.tcode].filter(Boolean).join(' · ');
437	    nodes.push({ id: 's', type: 'start', label: mIn ? mIn[1].trim() : t.flow.start });
438	    nodes.push({ id: 'p', type: 'process', label: sub ? `${r.l5 || r.code}\n${sub}` : (r.l5 || r.code) });
439	    nodes.push({ id: 'e', type: 'end', label: mOut ? mOut[1].trim() : t.flow.end });
440	    chain(['s', 'p', 'e']);
441	    return { nodes, edges };
442	  }
443	  const kids = [];
444	  for (let i = idx + 1; i < rows.length; i++) {
445	    const c = rows[i];
446	    if (c.lv <= r.lv) break;
447	    if (c.lv === r.lv + 1) kids.push(c);
448	  }
449	  if (!kids.length) return null;
450	  nodes.push({ id: 's', type: 'start', label: t.flow.start });
451	  const ids = ['s'];
452	  kids.forEach((k, i) => {
453	    const lbl = k[`l${k.lv}`] || k.task_desc || k.code;
454	    const sub = k.lv === 5 ? [k.program, k.tcode].filter(Boolean).join(' · ') : '';
455	    nodes.push({ id: `n${i}`, type: 'process', label: sub ? `${lbl}\n${sub}` : lbl });
456	    ids.push(`n${i}`);
457	  });
458	  nodes.push({ id: 'e', type: 'end', label: t.flow.end });
459	  ids.push('e');
460	  chain(ids);
461	  return { nodes, edges };
462	}
463	
464	const anchorOf = (code) => `bpml-${String(code).replace(/[^0-9A-Za-z]+/g, '-')}`;
465	
466	// ── Markdown mode — same data, Excel parity: overview section + full BPML
467	//    staircase table + per-row detail sections (L2–L5 each: title +
468	//    description + flow SVG under `_img/bpml-flows-<lang>/`; process-code
469	//    cells hyperlink to their section). Warn cells get a "⚠ " prefix
470	//    (md has no yellow fill); L1 rows render bold. Sheet-name rule carries
471	//    over: BPML heading is always English "BPML", overview heading localized.
472	export function buildBpmlMd({ meta = {}, rows = [], outPath }) {
473	  if (!outPath) throw new Error('build-bpml: outPath is required');
474	  if (!Array.isArray(rows) || rows.length === 0) throw new Error('build-bpml: rows[] is empty');
475	  const t = pickLang(meta);
476	  const counts = {};
477	  for (const r of rows) counts[r.lv] = (counts[r.lv] || 0) + 1;
478	  assignProcIds(meta, rows);
479	
480	  const md = (v) => String(v ?? '').replace(/\|/g, '\\|').replace(/\r?\n/g, '<br>');
481	  const L = [];
482	  L.push(`# ${meta.package || ''} — ${t.title}`, '');
483	
484	  L.push(`## ${t.ov.pkgBand}`, '');
485	  const kv = (label, value) => { if (value) L.push(`- **${label}**: ${md(value)}`); };
486	  kv(t.ov.package, meta.package);
487	  kv(t.ov.module, meta.module);
488	  kv(t.ov.sapVersion, meta.sap_version);
489	  kv(t.ov.abapRelease, meta.abap_release);
490	  kv(t.ov.industry, meta.industry);
491	  kv(t.ov.country, meta.country);
492	  kv(t.ov.activeModules, (meta.active_modules || []).join(', '));
493	  kv(t.ov.generatedAt, meta.generated_at);
494	  kv(t.ov.language, meta.language);
495	  kv(t.ov.levelCounts, `L1 ${counts[1] || 0} · L2 ${counts[2] || 0} · L3 ${counts[3] || 0} · L4 ${counts[4] || 0} · L5 ${counts[5] || 0}`);
496	  L.push('');
497	
498	  const eps = meta.entry_points || [];
499	  if (eps.length) {
500	    L.push(`## ${t.ov.epBand}`, '');
501	    L.push(`| ${t.ov.epProgram} | ${t.ov.epTcode} | ${t.ov.epShort} | ${t.ov.epPersona} |`);
502	    L.push('|---|---|---|---|');
503	    for (const e of eps) L.push(`| ${md(e.program)} | ${md(e.tcode || '-')} | ${md(e.short)} | ${md(e.persona)} |`);
504	    L.push('');
505	  }
506	
507	  const leg = meta.wricef_legend || {};
508	  if (Object.keys(leg).length) {
509	    L.push(`## ${t.ov.legendBand}`, '');
510	    for (const k of Object.keys(leg)) L.push(`- **${md(k)}**: ${md(leg[k])}`);
511	    L.push('');
512	  }
513	
514	  L.push('<a id="bpml-table" name="bpml-table"></a>', '');
515	  L.push('## BPML', '');
516	  // task_desc header padded with &nbsp; so HTML renderers give the column
517	  // generous min-width instead of squeezing it between 16 siblings.
518	  const hdr = (c) => t.headers[c.key] + (c.key === 'task_desc' ? '&nbsp;'.repeat(60) : '');
519	  L.push(`| ${COLUMNS.map(hdr).join(' | ')} |`);
520	  L.push(`|${COLUMNS.map((c) => (c.center ? ':---:' : '---')).join('|')}|`);
521	  for (const r of rows) {
522	    const cells = COLUMNS.map((c) => {
523	      const raw = r[c.key];
524	      let v = md(raw);
525	      if (isWarn(raw)) v = `⚠ ${v}`;
526	      if (r.lv === 1 && v && (c.key === 'code' || c.key === 'l1')) v = `**${v}**`;
527	      if (c.key === 'code' && r.lv >= 2 && v) v = `[${v}](#${anchorOf(r.code)})`;
528	      return v;
529	    });
530	    L.push(`| ${cells.join(' | ')} |`);
531	  }
532	  L.push('');
533	
534	  // ── Per-row detail sections (L2–L5, document order) ──────────────────
535	  const lang2 = String(meta.language || 'ko').toLowerCase().slice(0, 2);
536	  const flowDirName = `_img/bpml-flows-${lang2}`;
537	  const flowDir = join(dirname(outPath), ...flowDirName.split('/'));
538	  let flowCount = 0, seqCount = 0;
539	  const detail = rows.some((r) => r.lv >= 2);
540	  if (detail) {
541	    L.push(`## ${t.flow.detailBand}`, '');
542	    rows.forEach((r, idx) => {
543	      if (!r.lv || r.lv < 2) return;
544	      const label = r[`l${r.lv}`] || '';
545	      L.push(`<a id="${anchorOf(r.code)}" name="${anchorOf(r.code)}"></a>`, '');
546	      L.push(`### [L${r.lv}] ${md(r.code)} ${md(label)}`.trimEnd(), '');
547	      if (r.lv === 5) {
548	        const facts = [r.proc_id && `**${r.proc_id}**`, r.program, r.tcode, r.wricef && `WRICEF: ${r.wricef}`]
549	          .filter(Boolean).map(md).join(' · ');
550	        if (facts) L.push(facts, '');
551	      }
552	      const desc = r.desc || r.task_desc;
553	      if (desc) L.push(`${md(desc)}`, '');
554	      // Image preference: row.seq (v13 horizontal scenario sequence diagram —
555	      // same style as the process document) → row.flow / auto-derived
556	      // vertical flowchart as fallback.
557	      let svg = null;
558	      if (r.seq && Array.isArray(r.seq.actors) && r.seq.actors.length) {
559	        svg = renderSequenceDiagramSVG(r.seq, { lang: lang2, title: `${r.code} ${label}`.trim() });
560	        seqCount++;
561	      } else {
562	        const graph = autoFlowGraph(rows, idx, t);
563	        if (graph) {
564	          svg = renderFlowchartSVG(graph, { lang: lang2, heading: `${r.code} ${label}`.trim() });
565	          flowCount++;
566	        }
567	      }
568	      if (svg) {
569	        const fname = `flow-${anchorOf(r.code)}.svg`;
570	        mkdirSync(flowDir, { recursive: true });
571	        writeFileSync(join(flowDir, fname), svg, 'utf8');
572	        L.push(`![${md(r.code)} flow](${flowDirName}/${fname})`, '');
573	      }
574	      L.push(`[${t.flow.backToTable}](#bpml-table)`, '');
575	    });
576	  }
577	
578	  L.push(`## ${t.ov.guideBand}`, '');
579	  L.push(`> ⚠ ${t.ov.guide}`, '');
580	
581	  const buf = Buffer.from(L.join('\n'), 'utf8');
582	  mkdirSync(dirname(outPath), { recursive: true });
583	  writeFileSync(outPath, buf);
584	  return { outPath, bytes: buf.length, rows: rows.length, counts, seqs: seqCount, flows: flowCount };
585	}
586	
587	const thisFile = fileURLToPath(import.meta.url);
588	if (process.argv[1] && resolve(process.argv[1]) === thisFile) {
589	  const [jsonPath, outPath] = process.argv.slice(2);
590	  if (!jsonPath || !outPath) {
591	    console.error('Usage: node build-bpml.mjs <bpml.json> <out.xlsx|out.md>');
592	    process.exit(2);
593	  }
594	  try {
595	    const spec = JSON.parse(readFileSync(resolve(jsonPath), 'utf8'));
596	    const build = outPath.toLowerCase().endsWith('.md') ? buildBpmlMd : buildBpml;
597	    const res = build({ meta: spec.meta, rows: spec.rows, outPath: resolve(outPath) });
598	    const lv = Object.entries(res.counts).map(([k, v]) => `L${k}:${v}`).join(' ');
599	    const fl = res.flows != null ? `, ${res.seqs || 0} seq + ${res.flows} flow SVGs` : '';
600	    console.log(`build-bpml: wrote ${res.outPath} (${res.bytes} bytes, ${res.rows} rows — ${lv}${fl})`);
601	  } catch (e) {
602	    console.error(`build-bpml: ${e.message}`);
603	    process.exit(1);
604	  }
605	}
