    outPath, bytes: buf.length, rows: rows.length, counts,
    flowSheets: groups.length, images: mediaSeq,
    imgCached: imgStat?.cached ?? 0, imgRendered: imgStat?.rendered ?? 0, imgFailed: imgStat?.failed ?? 0,
  };
}
