    console.error('Usage: node build-bpml.mjs <bpml.json> <out.xlsx|out.md>');
    process.exit(2);
  }
  try {
    const spec = JSON.parse(readFileSync(resolve(jsonPath), 'utf8'));
    const build = outPath.toLowerCase().endsWith('.md') ? buildBpmlMd : buildBpml;
    const res = build({ meta: spec.meta, rows: spec.rows, outPath: resolve(outPath) });
    const lv = Object.entries(res.counts).map(([k, v]) => `L${k}:${v}`).join(' ');
    const fl = res.flows != null ? `, ${res.seqs || 0} seq + ${res.flows} flow SVGs` : '';
    console.log(`build-bpml: wrote ${res.outPath} (${res.bytes} bytes, ${res.rows} rows — ${lv}${fl})`);
  } catch (e) {
    console.error(`build-bpml: ${e.message}`);
    process.exit(1);
  }
}

