try {
  $wb = $excel.Workbooks.Open($p, 0, $true)
  for ($si = 3; $si -le 7; $si++) {
    $s = $wb.Worksheets.Item($si)
    # collect heading band rows: cells in col A with '[L' prefix
    $headTops = @()
    $used = $s.UsedRange.Rows.Count
    for ($r = 4; $r -le $used; $r++) {
      $v = $s.Cells.Item($r, 1).Text
      if ($v -like "``[L*") { $headTops += [pscustomobject]@{ Row = $r; Top = $s.Rows.Item($r).Top } }
    }
    $overlap = 0
    foreach ($sh in $s.Shapes) {
      $bot = $sh.Top + $sh.Height
      foreach ($h in $headTops) {
        if ($sh.Top -lt $h.Top -and $bot -gt $h.Top) { $overlap++; Write-Output ("  OVERLAP sheet $si shape " + $sh.TopLeftCell.Address + " bottom " + [math]::Round($bot) + " crosses heading row " + $h.Row) }
      }
    }
    Write-Output ("sheet " + $si + " (" + $s.Name + "): shapes=" + $s.Shapes.Count + " headings=" + $headTops.Count + " overlaps=" + $overlap)
  }
  $wb.Close($false)
} finally {
  try { $excel.Quit() } catch {}
  [System.Runtime.Interopservices.Marshal]::ReleaseComObject($excel) | Out-Null
}

